`PRIMARY DOCUMENT

Filename: ${doc.name}

The user's questions should be answered using this document.

${doc.content}`
        });

    } else {

        // Multiple documents attached.
        // Present the first as the current document and clearly separate the rest.
        const [primary, ...others] = docs;

        adhocParts.push({
            text:
`PRIMARY DOCUMENT

Filename: ${primary.name}

The user's current questions most likely refer to this document unless they explicitly ask to compare documents.

${primary.content}`
        });

        if (others.length) {

            const otherText = others
                .map(doc =>
`### ${doc.name}

${doc.content}`)
                .join("\n\n--------------------------------------------------\n\n");

            adhocParts.push({
                text:
`ADDITIONAL REFERENCE DOCUMENTS

These documents may provide supporting context if needed.

${otherText}`
            });

        }

    }

}

// Cacheable context (KB docs + images).
// Large documents are searched (BM25) and only the best-matching excerpts are sent,
// keeping each turn far below Gemini's per-minute input token quota.
const RETRIEVAL_BUDGET_TOKENS = 60000;
const CHUNK_CHARS = 4800;
const REGION_CHUNKS = 12;
const MAX_CHUNKS_PER_REGION = 6;
const WHOLE_DOCUMENT_PATTERN = /\b(summar(y|ise|ize)|overview|whole (book|document|text)|entire (book|document)|all (the )?chapters|outline of the|main (themes|ideas|points|arguments))\b/i;
const STOP_WORDS = new Set('the and for that this what does how why about with are was his her its from they them their there which who whom when where can could would should will into than then also not but you your yours our out has have had been being were more most some such only other any each very just like over under book chapter author explain tell describe give example examples please help understand simple simply'.split(' '));

const estimateTokens = text => Math.ceil(text.length / 4);
const toTerms = text => (text.toLowerCase().match(/[a-z]{3,}|\d{2,}/g) || [])
  .filter(word => !STOP_WORDS.has(word))
  .map(word => word.replace(/(ing|ed|es|s)$/, ''));

function chunkDocument(doc, docIndex) {
  const chunks = [];
  let buffer = '';
  let page = null;
  let chunkPage = null;
  const flush = () => {
    if (buffer.trim()) chunks.push({ docIndex, name: doc.name, page: chunkPage, text: buffer.trim() });
    buffer = '';
    chunkPage = page;
  };
  for (const paragraph of doc.content.split(/\n\s*\n/)) {
    const markers = paragraph.match(/\[(?:Scan )?[Pp]age (\d+)\]/g);
    if (markers) page = Number(markers.at(-1).match(/\d+/)[0]);
    if (chunkPage === null) chunkPage = page;
    buffer += paragraph + '\n\n';
    if (buffer.length > CHUNK_CHARS) flush();
  }
  flush();
  return chunks;
}

function selectExcerpts(docs, query) {
  const chunks = docs.flatMap(chunkDocument);
  const indexed = chunks.map(chunk => {
    const frequencies = {};
    const terms = toTerms(chunk.text);
    for (const term of terms) frequencies[term] = (frequencies[term] || 0) + 1;
    return { frequencies, length: terms.length };
  });
  const documentFrequency = {};
  for (const { frequencies } of indexed) for (const term in frequencies) documentFrequency[term] = (documentFrequency[term] || 0) + 1;
  const averageLength = indexed.reduce((sum, d) => sum + d.length, 0) / Math.max(indexed.length, 1);
  const queryTerms = [...new Set(toTerms(query))];
  const ranked = indexed.map((d, i) => {
    let score = 0;
    for (const term of queryTerms) {
      const frequency = d.frequencies[term];
      if (!frequency) continue;
      const idf = Math.log(1 + (indexed.length - documentFrequency[term] + 0.5) / (documentFrequency[term] + 0.5));
      score += idf * frequency * 2.2 / (frequency + 1.2 * (0.25 + 0.75 * d.length / averageLength));
    }
    return { score, i };
  }).filter(r => r.score > 0).sort((a, b) => b.score - a.score);

  const selected = [];
  const perRegion = {};
  let used = 0;
  for (const { i } of ranked) {
    const region = `${chunks[i].docIndex}:${Math.floor(i / REGION_CHUNKS)}`;
    if ((perRegion[region] || 0) >= MAX_CHUNKS_PER_REGION) continue;
    const tokens = estimateTokens(chunks[i].text);
    if (used + tokens > RETRIEVAL_BUDGET_TOKENS) continue;
    selected.push(i);
    perRegion[region] = (perRegion[region] || 0) + 1;
    used += tokens;
  }
  return selected.sort((a, b) => a - b).map(i => chunks[i]);
}

const cacheableParts = [];
const referenceDocs = (body.cachableContext || []).filter(c => c.content);
if (referenceDocs.length > 0) {
  const userMessages = (body.messages || []).filter(m => m.role === 'user').map(m => m.text || '');
  const latestQuestion = userMessages.at(-1) || '';
  const totalTokens = referenceDocs.reduce((sum, c) => sum + estimateTokens(c.content), 0);
  const sendWholeDocuments = totalTokens <= RETRIEVAL_BUDGET_TOKENS || WHOLE_DOCUMENT_PATTERN.test(latestQuestion);

  if (sendWholeDocuments) {
    const ctxText = referenceDocs.map(c => `### ${c.name}\n${c.content}`).join('\n\n');
    cacheableParts.push({ text: 'Reference material — treat this as the source of truth:\n\n' + ctxText });
  } else {
    const excerpts = selectExcerpts(referenceDocs, userMessages.slice(-2).join('\n'));
    const excerptText = excerpts
      .map(e => `### ${e.name}${e.page ? ` (scan page ${e.page})` : ''}\n${e.text}`)
      .join('\n\n[…]\n\n');
    cacheableParts.push({
      text:
`Reference material — relevant excerpts found by searching: ${referenceDocs.map(c => c.name).join(', ')}.
These are excerpts, not the full documents. Treat them as the source of truth.
If they don't contain the answer, say the retrieved sections didn't cover it and ask the student which chapter, section or topic to look in — don't claim the document lacks it.

${excerptText || '(No matching sections found for this question.)'}`
    });
  }
}
for (const img of (body.attachedImages || [])) {
  if (!img.data) continue;
  cacheableParts.push({ text: `Attached image: ${img.name}` });
  cacheableParts.push({ inline_data: { mime_type: img.mime || 'image/jpeg', data: img.data } });
}

// Scanned PDFs — handed to Gemini via Files API; n8n owns upload/reuse
// (see "Upload Scanned PDFs"). Cheap to resend every turn: it's just a
// file_uri reference, not the document bytes.
for (const part of (input.geminiFileParts || [])) {
