}

const contents = [];

/*
 * 1. Reference material FIRST
 * This is the authoritative source.
 */
if (adhocParts.length || cacheableParts.length) {

    contents.push({
        role: "user",
        parts: [
            {
                text:
`REFERENCE MATERIAL

The following material is the authoritative source for this conversation.

If any previous assistant response contradicts this material,
the previous response is WRONG.

Always answer using the reference material below.`
            },
            ...adhocParts,
            ...cacheableParts
        ]
    });

}

/*
 * 2. Previous conversation
 */
const MAX_HISTORY = 30;

// A job run (re-run after a lost attempt) never sees its own earlier answer: entries tagged with this jobId are skipped.
const jobId = $('Normalize Multipart Body').first().json._job?.id;
const previousConversation =
    (session?.conversation || [])
        .filter(m => !jobId || !m || m.jobId !== jobId)
        .slice(-MAX_HISTORY);

for (const m of previousConversation) {

    contents.push({
        role: m.role,
        parts: [
            {
                text: m.text
            }
        ]
    });

}

/*
 * 3. Latest user messages
 */
const latestMessage = body.messages?.at(-1);

if (latestMessage) {

    contents.push({
        role: viaJwt ? 'user' : latestMessage.role,
