        if (upRes && !upRes.is_oa) note = 'This source may not be Open Access. Verify permissions before relying on full text.';
      } catch (e) {}
    } else {
      note = 'Academic source detected. Verify this source is OA/permitted before relying on full text.';
    }
  }
} catch (e) {}

return [{ json: { text: html, ytUploadDate, note } }];

const body = $json.body || {};
const style = body.style || 'Harvard';
const src = body.source || {};
const kind = src.kind || 'link';
const label = src.label || '';
const meta = src.meta || {};


// Build a source-specific context block
let sourceBlock = '';
if (kind === 'link') {
  sourceBlock = `TYPE: Web article / page
URL: ${label}
SCRAPED PAGE TEXT (first ~4000 chars):
${(meta.scrapedText || '').slice(0, 4000)}`;
} else if (kind === 'youtube') {
  sourceBlock = `TYPE: YouTube video
URL: ${meta.url || label}
TITLE: ${meta.title || label}
CHANNEL / AUTHOR: ${meta.author || ''}
SCRAPED PAGE TEXT (for upload year + description, first ~3000 chars):
${(meta.scrapedText || '').slice(0, 3000)}`;
} else if (kind === 'kb') {
  sourceBlock = `TYPE: Uploaded document (from student's Knowledge Bay)
FILE NAME: ${label}
DOCUMENT TEXT (first ~4000 chars):
${(meta.content || '').slice(0, 4000)}`;
} else if (kind === 'upload') {
  sourceBlock = `TYPE: Newly uploaded document
FILE NAME: ${label}
DOCUMENT TEXT (first ~4000 chars):
${(meta.content || '').slice(0, 4000)}`;
}

const styleRules = {
  Harvard:  "Harvard referencing style (author-date). Format: Surname, Initial. (Year) 'Title', Source, Available at: URL (Accessed: date). Use italics conventions via plain text.",
  APA:      "APA 7th edition. Format: Surname, I. (Year). Title. Source. URL",
  MLA:      "MLA 9th edition. Format: Surname, First Name. \"Title.\" Source, Day Month Year, URL.",
  Chicago:  "Chicago (author-date). Format: Surname, First Name. Year. \"Title.\" Source. URL.",
};

const prompt = `You are a citation generator. Produce ONE correctly formatted reference in ${style} style for the source below.

STYLE RULES: ${styleRules[style] || styleRules.Harvard}

RULES:
- Output ONLY the finished reference line — no preamble, no explanation, no bullet, no quotes around the whole thing.
- If the exact year, author, or title is missing, infer the most likely value from the provided text. Never output placeholders like "n.d." unless there is genuinely no date clue anywhere.
- For YouTube: author = channel name, title = video title, year = upload year from the scraped page.
- For uploaded documents with no explicit author, use the filename (without extension) as the title and write "Anon." as author only if no author appears in the document text.
- Use a hanging-indent-ready single line (no manual line breaks).

SOURCE:
${sourceBlock}

Now output the single ${style} reference line:`;

return [{
  json: {
    geminiBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0.2,
        maxOutputTokens: 800
      }
    }
  }
}];

const response = $('Reference').first().json;
let citation = '';

try {
  if (response.body && response.body.candidates && response.body.candidates.length > 0) {
    const parts = response.body.candidates[0].content?.parts || [];
    citation = parts.map(p => p.text || '').join('');
  }
  if (!citation && response.candidates && response.candidates.length > 0) {
    citation = (response.candidates[0].content?.parts || []).map(p => p.text || '').join('');
  }
} catch (e) { citation = ''; }

citation = citation
  .replace(/^```[\w]*\s*/i, '')
  .replace(/\s*```$/i, '')
  .replace(/^["']|["']$/g, '')
  .trim();

if (!citation) citation = '[Unable to generate citation — please check the source]';

return [{ json: { citation } }];

const body = $input.first().json.body;

function hashDocs(fingerprints) {
  const str = (fingerprints || [])
    .slice()
    .sort((a, b) => a.id.localeCompare(b.id))
    .map(f => `${f.id}:${f.updatedAt}:${f.size}`)
    .join('|');

  let h = 5381;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) + h + str.charCodeAt(i)) | 0;
  }

  return (h >>> 0).toString(16);
}

return [{
  json: {
    body,
    sessionId: body.chatId,
    documentHash: hashDocs(body.documentFingerprints)
  }
}];

const load = $('Load Session').first().json;
const redisResponse = $input.first().json;

let session = {
  conversation: []
};

try {
