    session = typeof redisResponse.result === 'string'
      ? JSON.parse(redisResponse.result)
      : redisResponse.result;
  }
} catch (e) {
  session = { conversation: [] };
}

const currentHash = load.documentHash;

if (
    session.documentHash &&
    session.documentHash !== currentHash
) {

    session = {
        conversation: [],
        documentHash: currentHash
    };

}

return [{
