const prep = $('Prep — Tutor').first().json;
const parsed = $('Scanned PDF Resolution Complete').first().json;

const previous = parsed.session || {};

const tutor = $('Extract Tutor Text').first().json;
const assistant = tutor.result;

const latestUser =
    parsed.body.messages.at(-1);

// Stored session stays small: last 30 entries, each capped (TTL stays 3 h)
const MAX_STORED_ENTRIES = 30;
const MAX_ENTRY_CHARS = 8000;
const capConversation = list => list.slice(-MAX_STORED_ENTRIES).map(m => (m && typeof m.text === 'string' && m.text.length > MAX_ENTRY_CHARS) ? { ...m, text: m.text.slice(0, MAX_ENTRY_CHARS) + '\n…[truncated]' } : m);

const conversation = [
    ...(previous.conversation || [])
];

// Job run: the pair of this job replaces an earlier pair of the same jobId (a re-run after a lost attempt must not duplicate it)
const jobId = $('Normalize Multipart Body').first().json._job?.id;
const jobTag = jobId ? { jobId } : {};
if (jobId) {
    for (let i = conversation.length - 1; i >= 0; i--) if (conversation[i] && conversation[i].jobId === jobId) conversation.splice(i, 1);
}

if (!tutor.failed) {
    if (latestUser) {
        conversation.push({
            role: latestUser.role,
            text: latestUser.text,
            ...jobTag
        });
    }

    conversation.push({
        role: "model",
        text: assistant,
        ...jobTag
    });
}

const now = Date.now();

const currentDocs = parsed.body.attachedContext || [];

const session = {
    schemaVersion: 1,

    id: prep.sessionId,

    createdAt: previous.createdAt ?? now,

    expiresAt: now + 10800 * 1000,

    documentHash: prep.documentHash,

    documents: currentDocs.map(d => ({
        name: d.name,
        hash: prep.documentHash
    })),

    conversation: capConversation(conversation),

    geminiFiles: parsed.updatedGeminiFiles || previous.geminiFiles || {},
};

return [{
    json: {
        sessionKey: `session:${prep.sessionId}`,
        sessionValue: JSON.stringify(session),
        reuploadScannedPdfs: parsed.reuploadScannedPdfs || []
    }
}];

const tutor = $('Extract Tutor Text').first().json;
const saved = $('Save Session Builder').first().json;

return [{
  json: {
    result: tutor.result,
    reuploadScannedPdfs: saved.reuploadScannedPdfs || []
  }
}];

// Normalizes the request body (multipart "payload" field merged in). v4: a background job run enters here from
// "Job - Admitted?" and reads the original request straight from "Job Start Endpoint" (no extra copy of the body).
// The job record {id, attempt, mode, startedAt, deadlineAt} is added as `_job` at the TOP LEVEL of the item, which a
// client cannot set; `body.job` (the client's envelope) is removed, and the mode in the body must equal the job's mode.
const fromJob = $('Job Start Endpoint').isExecuted;
const item = fromJob ? $('Job Start Endpoint').first() : $input.first();
let body = item.json.body || {};

if (typeof body.payload === 'string') {
  let parsed;
  try {
    parsed = JSON.parse(body.payload);
  } catch (e) {
    // A job error must never carry a piece of the request: the parser message can quote it.
    if (fromJob) throw new Error('STH-INPUT-400 Malformed multipart "payload" field');
    throw new Error('Malformed multipart "payload" field: ' + e.message);
  }
  body = { ...body, ...parsed };
  delete body.payload;
}

let _job;
if (fromJob) {
  _job = $('Job - Admit Result').first().json.job;
  delete body.job;
  if (!_job || body.mode !== _job.mode) throw new Error('STH-INPUT-400 The job mode does not match the request');
}

return [{ json: { ...item.json, body, ...(_job ? { _job } : {}) }, binary: item.binary }];

const item = $input.first();
const body = item.json.body || {};
const docs = body.scannedPdfDocs || [];

if (docs.length > 0) {
  const doc = docs[0]; // single-scanned-PDF-per-request, matching real usage
  let base64 = null;

  if (doc.fieldName) {
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(0, doc.fieldName);
      base64 = buffer.toString('base64');
    } catch (e) {
      base64 = null;
    }
  }

  body.scannedPdfDocs = [{ ...doc, base64 }, ...docs.slice(1)];
}

return [{ json: { ...item.json, body } }];

const parse = $('Parse Session').first().json;
const redisRes = $input.first().json;
const doc = parse.body.scannedPdfDocs[0];
const now = Date.now();

let persistentFile = null;
try { if (redisRes.result) persistentFile = JSON.parse(redisRes.result); } catch (e) {}

const sessionFiles = (parse.session && parse.session.geminiFiles) || {};
const sessionFile = doc.contentHash ? sessionFiles[doc.contentHash] : null;

const cached =
  (sessionFile && sessionFile.expiresAt > now) ? sessionFile :
  (persistentFile && persistentFile.expiresAt > now) ? persistentFile :
  null;

return [{ json: { ...parse, doc, cached } }];

const d = $input.first().json;
const parts = [
  { text: `Attached PDF: ${d.doc.name}${d.doc.pageCount ? ` (${d.doc.pageCount} pages)` : ''}` },
