];
const sessionFiles = { ...((d.session && d.session.geminiFiles) || {}) };
if (d.doc.contentHash) sessionFiles[d.doc.contentHash] = d.cached;
return [{ json: { ...d, geminiFileParts: parts, reuploadScannedPdfs: [], updatedGeminiFiles: sessionFiles, newPersistentEntry: null } }];

const d = $input.first().json;
const doc = d.doc;

if (!doc.base64) {
