    }
  }];
}

return [{ json: { ...d, skipUpload: false } }];

const d = $input.first().json;
const buffer = Buffer.from(d.doc.base64, 'base64');
if (buffer.length > 50 * 1024 * 1024) {
  throw new Error(`FILE_TOO_LARGE: "${d.doc.name}" is ${(buffer.length / 1024 / 1024).toFixed(1)}MB, over Gemini's 50MB PDF limit`);
}
const binaryData = await this.helpers.prepareBinaryData(buffer, d.doc.name, 'application/pdf');
return [{ json: { ...d, byteLength: buffer.length }, binary: { pdfFile: binaryData } }];

const res = $input.first().json;
const headers = res.headers || {};
const uploadUrl = headers['x-goog-upload-url'] || headers['X-Goog-Upload-URL'] || null;
const prev = $('Convert Base64 To Binary').first().json;
if (!uploadUrl) throw new Error(`GEMINI_FILE_UPLOAD: no upload URL returned for "${prev.doc.name}"`);
return [{ json: { ...prev, uploadUrl }, binary: $('Convert Base64 To Binary').first().binary }];

const res = $input.first().json;
const uploaded = res.file || res;
const prev = $('Extract Upload URL').first().json;
if (!uploaded || !uploaded.uri) throw new Error(`GEMINI_FILE_UPLOAD: no file URI returned for "${prev.doc.name}"`);
return [{ json: { ...prev, geminiFileName: uploaded.name, geminiUri: uploaded.uri, geminiMimeType: uploaded.mimeType || 'application/pdf', geminiState: uploaded.state, geminiPollStartedAt: Date.now(), geminiPollAttempts: 0 } }];

const d = $input.first().json;
const record = { uri: d.geminiUri, mimeType: d.geminiMimeType, expiresAt: Date.now() + 47 * 60 * 60 * 1000 };
const parts = [
  { text: `Attached PDF: ${d.doc.name}${d.doc.pageCount ? ` (${d.doc.pageCount} pages)` : ''}` },
  { file_data: { mime_type: d.geminiMimeType, file_uri: d.geminiUri } },
];
const sessionFiles = { ...((d.session && d.session.geminiFiles) || {}) };
if (d.doc.contentHash) sessionFiles[d.doc.contentHash] = record;
return [{
  json: {
    ...d,
    geminiFileParts: parts,
    reuploadScannedPdfs: [],
