}];

const res = $input.first().json;
const prev = $('Extract Uploaded File').first().json;
const now = Date.now();
const startedAt = prev.geminiPollStartedAt || now;
const attempts = (prev.geminiPollAttempts || 0) + 1;

if (res.state === 'FAILED') {
  throw new Error(`GEMINI_FILE_PROCESSING_FAILED: Gemini failed to process "${prev.doc.name}"`);
}
if (res.state !== 'ACTIVE' && res.state !== 'PROCESSING') {
  throw new Error(`GEMINI_FILE_PROCESSING_FAILED: unexpected state "${res.state}" for "${prev.doc.name}"`);
}
if (res.state !== 'ACTIVE' && (now - startedAt) > 60000) {
  throw new Error(`GEMINI_FILE_PROCESSING_TIMEOUT: "${prev.doc.name}" did not become ACTIVE within 60s`);
}

return [{
  json: {
    ...prev,
    geminiUri: res.uri || prev.geminiUri,
    geminiMimeType: res.mimeType || prev.geminiMimeType,
    geminiState: res.state,
    geminiPollStartedAt: startedAt,
    geminiPollAttempts: attempts,
  }
}];

const body = $('Normalize Multipart Body').first().json.body;
const redisRes = $input.first().json;
const doc = body.scannedPdfDocs[0];
const now = Date.now();

let cached = null;
try {
  if (redisRes.result) {
    const persistentFile = JSON.parse(redisRes.result);
    if (persistentFile.expiresAt > now) cached = persistentFile;
  }
} catch (e) {}

return [{ json: { doc, cached } }];

const d = $input.first().json;
const parts = [
  { text: `Attached PDF: ${d.doc.name}${d.doc.pageCount ? ` (${d.doc.pageCount} pages)` : ''}` },
  { file_data: { mime_type: d.cached.mimeType, file_uri: d.cached.uri } },
];
return [{ json: { ...d, scannedPdfParts: parts, newPersistentEntry: null } }];

const d = $input.first().json;
const doc = d.doc;

if (!doc.base64) {
