  if (isRateLimited && attempt + 1 === FALLBACK_FROM_ATTEMPT) {
    waitSeconds = 3;
  } else if (isRateLimited) {
    const hinted = parseFloat((res.body?.error?.message || '').match(/retry in ([\d.]+)s/i)?.[1]);
    waitSeconds = (Number.isFinite(hinted) ? Math.ceil(hinted) + 5 : 35) + Math.floor(Math.random() * 5);
  } else {
    waitSeconds = 5 * attempt;
  }
  waitSeconds = Math.min(waitSeconds, 60);
